import numpy as np, itertools
from numpy.linalg import lstsq
L=np.log(eps)
eb={'1':np.ones_like(eps),'L':L,'e':eps,'e2':eps**2,'eL':eps*L,'1/e':1/eps,'L2':L**2,'sqe':np.sqrt(eps),'e3':eps**3}
tb={'1':np.ones_like(T),'T':T,'1/T':1/T,'lnT':np.log(T),'T2':T**2}
feats={a+'*'+b:eb[a]*tb[b] for a in eb for b in tb}
names=list(feats)
best=[]
for k in range(3,7):
    for comb in itertools.combinations(names,k):
        X=np.vstack([feats[c] for c in comb]).T
        c=lstsq(X,sigma,rcond=None)[0]
        v=np.mean((sigma-X@c)**2)/np.var(sigma)
        best.append((v,comb))
best.sort()
for b in best[:6]: print(b)

